#!/usr/bin/env bash
# 设置字符编码，确保中文正常显示
{
    export LANG=C.UTF-8 2>/dev/null || export LANG=en_US.UTF-8 2>/dev/null || export LANG=POSIX 2>/dev/null || true
    export LC_ALL=C.UTF-8 2>/dev/null || export LC_ALL=en_US.UTF-8 2>/dev/null || export LC_ALL=POSIX 2>/dev/null || true
} 2>/dev/null
# 引入全局参数
[ -f /root/.gs/.env ] && . /root/.gs/.env
# 颜色代码
[ -f /usr/local/bin/color ] && . /usr/local/bin/color

# comment: 封号，解封号 (交互与 gstlenv 完全一致)
if [ ! -f /root/.gs/.env ]; then
    echo -e "${GSISSUE}\r\n"
    echo "${CRED}环境未初始化，需要重新安装或者移除现有的环境重新安装！！！${CEND}"
    exit 1
fi

TL_MYSQL_PASSWORD="${TL_MYSQL_PASSWORD:-123456}"
VALID_SETTINGS=''
INVALID_SETTINGS=''

if [ -z "$1" ]; then
    # 判断第一个参数是否为空
    echo -e "${CRED}请输入需要解封或者封号的账号！${CEND}"
    exit 1
else
    # 判断是否有第二个参数输入
    if [ -z "$2" ]; then
        # 表示是解封
        mysql -uroot -p"${TL_MYSQL_PASSWORD}" -e "UPDATE t_char SET settings = '${VALID_SETTINGS}' WHERE accname = '$1';" 2>/dev/null
        echo -e "${CSUCCESS}解封[$1]账号成功：登录游戏查看，如果未实现请退出游戏再执行一次${CEND}"
        exit 0
    else
        # 判断是否输入的是1，如果是1表示为封号
        if [ "$2" -eq 1 ] 2>/dev/null; then
            mysql -uroot -p"${TL_MYSQL_PASSWORD}" -e "UPDATE t_char SET settings = '${INVALID_SETTINGS}' WHERE accname = '$1';" 2>/dev/null
            echo -e "${CSUCCESS}封[$1]账号成功：登录游戏查看，如果未实现请退出游戏再执行一次${CEND}"
            exit 0
        else
            echo -e "${GSISSUE}\r\n"
            echo -e "${CRED}输入错误：如果需要封号，请在账号后面使用数字1即可封号！${CEND}"
            exit 1
        fi
    fi
fi